<section data-admin-page="import" data-title="Import Records" data-description="Add drivers or tricycles from a prepared CSV file." hidden>
    <x-admin.panel title="Upload a CSV File"><div class="ts-columns mb-4"><div class="ts-note"><h3>Step 1 — Choose a record type</h3><p>Only driver and tricycle records can be imported.</p></div><x-admin.field label="Import Type" name="import-type" type="select"><option value="drivers">Drivers</option><option value="tricycles">Tricycles</option></x-admin.field></div>
        <label class="ts-dropzone" id="csv-dropzone" for="csv-file"><strong>Choose a UTF-8 CSV file</strong><span>Click to select or drop a prepared file · Up to 1 MB / 1,000 records</span><input type="file" class="form-control" id="csv-file" accept=".csv,text/csv" aria-describedby="csv-help csv-status"></label>
        <p id="csv-help" class="ts-muted mt-3">Required columns: name, contact, type (Regular or Substitute).</p><button class="ts-text-button" type="button" id="csv-template">Download sample CSV template</button><p id="csv-status" role="status" class="ts-muted mt-2 mb-0">No file selected. Choose a CSV to preview its records.</p>
    </x-admin.panel>
    <x-admin.panel title="Preview and Validate"><p class="ts-muted">Step 2 — Check records before importing.</p><div class="table-responsive" tabindex="0" role="region" aria-label="Scrollable sample records"><table class="table ts-table"><caption class="visually-hidden">CSV row validation preview</caption><thead><tr><th scope="col">CSV Row</th><th scope="col">Record</th><th scope="col">Validation</th><th scope="col">Reason</th></tr></thead><tbody id="csv-preview"></tbody></table></div><div class="d-flex justify-content-between gap-3 align-items-center flex-wrap"><p class="ts-muted mb-0">Invalid or duplicate rows are excluded from the preview.</p><button type="button" class="btn btn-primary" id="csv-confirm" disabled>Confirm Valid Rows</button></div></x-admin.panel>
</section>
